private void pop(final String descriptor){
    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, find the end of the argument types
        index = descriptor.indexOf(')');
        String argumentTypes = descriptor.substring(1, index);
        for (int i = 0; i < argumentTypes.length(); i++) {
            char c = argumentTypes.charAt(i);
            if (c == 'J' || c == 'D') {
                // double and long types take two slots
                i++;
            } else if (c == '[') {
                // array type, skip to the end of the array descriptor
                while (i < argumentTypes.length() && argumentTypes.charAt(i) == '[') {
                    i++;
                }
                if (i < argumentTypes.length()) {
                    c = argumentTypes.charAt(i);
                    if (c == 'L') {
                        // object type, skip to the end of the object descriptor
                        i = argumentTypes.indexOf(';', i) + 1;
                    }
                }
            } else if (c == 'L') {
                // object type, skip to the end of the object descriptor
                i = argumentTypes.indexOf(';', i) + 1;
            }
            // pop one slot for each type
            popSlot();
        }
    } else {
        // It's a type descriptor
        if (descriptor.charAt(0) == 'J' || descriptor.charAt(0) == 'D') {
            // double and long types take two slots
            popSlot();
        }
        popSlot();
    }
}

