        return null;
    }
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++; // Skip the backslash
            if (i < input.length()) {
                c = input.charAt(i);
                // Handle common escape sequences
                switch (c) {
                    case 'n':
                        output.append('\n');
                        break;
                    case 't':
                        output.append('\t');
                        break;
                    case 'r':
                        output.append('\r');
