private void pop(final String descriptor){
    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, find the end of the argument types
        index = descriptor.indexOf(')');
        String argumentTypes = descriptor.substring(1, index);
        for (int i = 0; i < argumentTypes.length(); i++) {
            char c = argumentTypes.charAt(i);
            if (c == 'J' || c == 'D') {
                // double and long types take two slots
                i++;
            } else if (c == '[' || c == 'L') {
                // array and object types take one slot
                // skip the rest of the descriptor for these types
                while (c != ';' && i < argumentTypes.length() - 1) {
                    c = argumentTypes.charAt(++i);
                }
            }
            // pop one slot for each type
            // Assuming there's a method popSlot() to pop one slot from the stack
            popSlot();
        }
    } else {
        // It's a field descriptor, pop based on the type
        char c = descriptor.charAt(0);
        if (c == 'J' || c == 'D') {
            // double and long types take two slots
            popSlot();
            popSlot();
        } else {
            // all other types take one slot
            popSlot();
        }
    }
}

