    int len = str.length();
    int utflen = 0;
    int c;

    for (int i = 0; i < len; i++) {
        c = str.charAt(i);
        if ((c >= 0x0001) && (c <= 0x007F)) {
            utflen++;
        } else if (c > 0x07FF) {
            utflen += 3;
        } else {
            utflen += 2;
        }
    }

    if (utflen > 65535) {
        throw new RuntimeException("encoded string too long: " + utflen + " bytes");
    }

    byte[] bytearr = new byte[utflen + 2];
    int count = 0;
